<script>
 import {onMount} from 'svelte';import {page} from '$app/stores';import {goto} from '$app/navigation';import {getMonitoring} from '$lib/api.js';import {locale} from '$lib/i18n.js';import {notify} from '$lib/stores.js';import {formatDate} from '$lib/date.js';import Button from '$lib/components/Button.svelte';import StatusDot from '$lib/components/StatusDot.svelte';
 let devices=[],loading=true,error='';$:ru=$locale!=='en';$:online=devices.filter(x=>x.status==='online').length;$:offline=devices.length-online;$:versions=[...new Set(devices.map(x=>x.agent_version).filter(Boolean))];
 async function load(){loading=true;error='';const r=await getMonitoring($page.url.searchParams.get('project_id')||'');if(r.ok)devices=r.data.devices||[];else{error=r.error||'Could not load Agent inventory';notify(error,'error')}loading=false}
 onMount(load);
</script>
<svelte:head><title>{ru?'Обслуживание Agent · Yevqo':'Agent maintenance · Yevqo'}</title></svelte:head>
<div class="page-header"><div><div class="eyebrow">SYSTEM / AGENT LIFECYCLE</div><h1 class="page-title">{ru?'Обслуживание Agent':'Agent maintenance'}</h1><p class="page-desc">{ru?'Версии, доступность и состояние подключённых Android + Termux Agent.':'Version, connectivity and health of connected Android + Termux Agents.'}</p></div><Button on:click={load} disabled={loading}>↻ {ru?'Проверить':'Refresh'}</Button></div>
{#if loading}<div class="empty">{ru?'Получаем состояние устройств…':'Loading device state…'}</div>{:else if error&&!devices.length}<div class="empty"><strong>{ru?'Не удалось получить состояние Agent':'Could not load Agent state'}</strong><p>{error}</p><Button on:click={load}>{ru?'Повторить':'Retry'}</Button></div>{:else}
<div class="metrics"><article><span>{ru?'Всего устройств':'Total devices'}</span><strong>{devices.length}</strong></article><article><span>{ru?'На связи':'Online'}</span><strong>{online}</strong></article><article><span>{ru?'Не на связи':'Offline'}</span><strong>{offline}</strong></article><article><span>{ru?'Обнаружено версий':'Versions detected'}</span><strong>{versions.length}</strong></article></div>
<section class="panel"><div class="panel-heading"><div><h2>{ru?'Инвентаризация Agent':'Agent inventory'}</h2><p>{ru?'Состояние берётся из последнего heartbeat Control Plane.':'State is based on the latest Control Plane heartbeat.'}</p></div><span class="count">{devices.length}</span></div>
{#if devices.length}<div class="device-list">{#each devices as d (d.id)}<article class="device"><div class="device-main"><div class="device-title"><strong>{d.hostname||'Android host'}</strong><StatusDot status={d.status}/></div><div class="device-meta"><span>{ru?'Agent':'Agent'} <b>{d.agent_version||'—'}</b></span><span>{d.platform||'Android / Termux'}</span><span>{d.site_count||0} {ru?'приложений':'applications'} · {d.running_sites||0} {ru?'работают':'running'}</span></div><small>{ru?'Последний heartbeat':'Last heartbeat'}: {d.last_seen?formatDate(d.last_seen):(ru?'не получен':'not received')}</small></div><a href={'/devices/'+d.id}>{ru?'Диагностика устройства →':'Device diagnostics →'}</a></article>{/each}</div>{:else}<div class="empty inner-empty"><strong>{ru?'Нет подключённых Agent':'No connected Agents'}</strong><p>{ru?'Подключи устройство через Termux, чтобы оно появилось в инвентаризации.':'Connect a device through Termux to add it to this inventory.'}</p><a href="/devices/connect">{ru?'Подключить устройство →':'Connect a device →'}</a></div>{/if}
</section>
<section class="notice"><div class="notice-icon">i</div><div><strong>{ru?'Обновление и восстановление':'Updates and recovery'}</strong><p>{ru?'Массовое обновление, rollback Agent и очистка хранилища не запускаются из этой сводки. Открой карточку конкретного устройства для поддерживаемых действий Agent. Команды выполняются только после подтверждения Agent.':'Bulk updates, Agent rollback and storage cleanup are not run from this overview. Open an individual device for supported Agent actions. Operations are only reported successful after Agent confirmation.'}</p></div></section>
{/if}
<style>
.eyebrow{font-size:9px;letter-spacing:.14em;color:var(--accent);font-weight:700;margin-bottom:7px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;margin-bottom:13px}.metrics article{padding:13px 15px;background:var(--bg-card);border:1px solid var(--border);border-radius:8px}.metrics span{display:block;color:var(--text-muted);font-size:10px}.metrics strong{display:block;margin-top:6px;font-size:22px;font-weight:650}.panel{border:1px solid var(--border);border-radius:8px;background:var(--bg-card);overflow:hidden}.panel-heading{display:flex;justify-content:space-between;align-items:center;padding:14px 16px;border-bottom:1px solid var(--border)}.panel-heading h2{font-size:12px}.panel-heading p{font-size:10px;color:var(--text-muted);margin-top:3px}.count{font:11px var(--mono);color:var(--text-muted)}.device{display:flex;align-items:center;gap:14px;padding:13px 16px;border-bottom:1px solid var(--border)}.device:last-child{border:0}.device-main{flex:1;min-width:0}.device-title{display:flex;align-items:center;gap:9px}.device-title strong{font-size:11px}.device-meta{display:flex;gap:13px;flex-wrap:wrap;margin:5px 0}.device-meta span,.device-main small{font-size:9px;color:var(--text-muted)}.device-meta b{color:var(--text-main);font-weight:550}.device>a,.inner-empty a{color:var(--accent);font-size:10px;white-space:nowrap}.inner-empty{border:0;background:transparent;padding:28px}.notice{display:flex;gap:11px;margin-top:13px;padding:13px 15px;background:var(--bg-card);border:1px solid var(--border);border-radius:8px}.notice-icon{width:22px;height:22px;display:grid;place-items:center;border-radius:50%;background:var(--bg-elevated);color:var(--accent);font-size:11px;flex:none}.notice strong{font-size:11px}.notice p{margin-top:4px;font-size:10px;line-height:1.6;color:var(--text-muted)}@media(max-width:850px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.metrics{grid-template-columns:1fr 1fr}.device{align-items:flex-start;flex-direction:column}.device>a{white-space:normal}}
</style>